@@ -0,0 +1,20 @@
+// Date formatting moved out of lib/format so the number helpers can be used
+// in the PDF worker, which has no Intl.DateTimeFormat locale data loaded.
+
+const DAY_MS = 86_400_000;
+
+export function formatDate(iso: string): string {
+  return new Date(iso).toLocaleDateString("en-US", {
+    year: "numeric",
+    month: "short",
+    day: "numeric",
+  });
+}
+
+export function formatRelative(iso: string, now = Date.now()): string {
+  const deltaDays = Math.round((now - Date.parse(iso)) / DAY_MS);
+  if (deltaDays === 0) return "today";
+  if (deltaDays === 1) return "yesterday";
+  if (deltaDays < 0) return `in ${-deltaDays} days`;
+  return `${deltaDays} days ago`;
+}

