+import { formatMoney, formatPercent } from "@/lib/format/number";

 import type { Invoice } from "@/lib/types";

 export function InvoiceRow({ invoice }: { invoice: Invoice }) {
   const overdue = invoice.dueAt < new Date().toISOString() && !invoice.paidAt;
   return (
     <tr data-overdue={overdue}>
       <td className="font-mono">{invoice.number}</td>
       <td>{formatDate(invoice.issuedAt)}</td>
       <td>{formatDate(invoice.dueAt)}</td>
       <td className="text-right">{formatMoney(invoice.totalCents)}</td>
       <td className="text-right">{formatPercent(invoice.taxRate)}</td>
     </tr>
   );
 }

