+++ b/src/lib/format/date.test.ts
@@ -0,0 +1,29 @@
+import { describe, expect, it } from "vitest";
+
+import { formatDate, formatRelative } from "./date";
+
+const NOW = Date.parse("2026-08-20T12:00:00Z");
+
+describe("formatDate", () => {
+  it("renders a short US date", () => {
+    expect(formatDate("2026-08-20T00:00:00Z")).toBe("Aug 20, 2026");
+  });
+});
+
+describe("formatRelative", () => {
+  it("says today for the same day", () => {
+    expect(formatRelative("2026-08-20T09:00:00Z", NOW)).toBe("today");
+  });
+
+  it("says yesterday for one day back", () => {
+    expect(formatRelative("2026-08-19T12:00:00Z", NOW)).toBe("yesterday");
+  });
+
+  it("counts days for older dates", () => {
+    expect(formatRelative("2026-08-10T12:00:00Z", NOW)).toBe("10 days ago");
+  });
+
+  it("handles future dates instead of returning a negative count", () => {
+    expect(formatRelative("2026-08-23T12:00:00Z", NOW)).toBe("in 3 days");
+  });
+});
